[DefaultExecutionOrder(1100)]public sealed class RiftModernMapFrame:MonoBehaviour {
 RiftFieldUI map;RectTransform sidebar;Button crystals,encounters;bool showCrystals=true,showEncounters=true;bool previousOpen;
 CanvasGroup gameplayVisibility;bool ownVisibility,oldBlocks,oldInteractable;float oldAlpha;
 static readonly Color Ink=new Color(.055f,.06f,.085f,.88f),Line=new Color(.34f,.34f,.44f,.65f),Violet=new Color(.58f,.37f,.95f),TextColor=new Color(.94f,.93f,.98f);
 public static void Install(RiftFieldUI owner){if(owner.GetComponent<RiftModernMapFrame>())return;owner.gameObject.AddComponent<RiftModernMapFrame>().Create(owner);}
 RectTransform Rect(Transform parent,string name,Vector2 min,Vector2 max,Vector2 pos,Vector2 size){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=min;r.anchorMax=max;r.pivot=new Vector2(.5f,.5f);r.anchoredPosition=pos;r.sizeDelta=size;return r;}
