 void Icon(Transform parent,HUDShape shape,Vector2 pos,Vector2 size,Color tint){var graphic=Rect(parent,"Map icon "+shape,new Vector2(0,1),new Vector2(0,1),pos,size).gameObject.AddComponent<RiftHUDGraphic>();graphic.Shape=shape;graphic.color=tint;graphic.Border=tint;graphic.Thickness=1.5f;graphic.raycastTarget=false;}
 Text Label(Transform p,string name,string value,Vector2 pos,Vector2 size,int font,TextAnchor alignment=TextAnchor.MiddleLeft){var r=Rect(p,name,new Vector2(0,1),new Vector2(0,1),pos,size);r.pivot=new Vector2(0,1);var text=r.gameObject.AddComponent<Text>();text.font=map.Theme.BodyFont;text.text=value;text.fontSize=font;text.color=TextColor;text.alignment=alignment;text.raycastTarget=false;return text;}
 Button Action(Transform p,string name,string value,Vector2 pos,Vector2 size,UnityEngine.Events.UnityAction clicked){var r=Rect(p,name,new Vector2(0,1),new Vector2(0,1),pos,size);r.pivot=new Vector2(0,1);var image=Surface(r,new Color(.12f,.11f,.19f,.58f),Line);image.raycastTarget=true;var b=r.gameObject.AddComponent<Button>();b.targetGraphic=image;var c=b.colors;c.normalColor=Color.white;c.highlightedColor=new Color(1.24f,1.15f,1.4f);c.pressedColor=new Color(.75f,.68f,.9f);c.selectedColor=c.highlightedColor;b.colors=c;b.onClick.AddListener(clicked);Label(r,"Label",value,new Vector2(54,0),size-new Vector2(66,0),17);return b;}
 void ToggleArt(Button button,HUDShape shape){Icon(button.transform,shape,new Vector2(25,-24),new Vector2(24,27),Violet);var label=button.GetComponentInChildren<Text>();label.rectTransform.sizeDelta=new Vector2(194,48);var track=Surface(Rect(button.transform,"Toggle track",new Vector2(1,.5f),new Vector2(1,.5f),new Vector2(-29,0),new Vector2(40,20)),Violet,new Color(.75f,.61f,1),10);var knob=Rect(track.transform,"Toggle knob",new Vector2(.5f,.5f),new Vector2(.5f,.5f),new Vector2(10,0),new Vector2(14,14)).gameObject.AddComponent<RiftHUDGraphic>();knob.Shape=HUDShape.Disc;knob.color=Color.white;knob.raycastTarget=false;}
 void Divider(Transform p,float y,float width){Fill(Rect(p,"Fine divider",new Vector2(0,1),new Vector2(0,1),new Vector2(width*.5f,y),new Vector2(width,1)),Line);}
 void Create(RiftFieldUI owner){map=owner;
  var old=map.MapPanel.GetComponent<RiftHUDGraphic>();if(old)old.enabled=false;
  var bg=Surface(Rect(map.MapPanel,"Smoked glass",Vector2.zero,Vector2.one,Vector2.zero,Vector2.zero),Ink,new Color(.5f,.47f,.64f,.9f),16);bg.raycastTarget=true;bg.transform.SetAsFirstSibling();
  foreach(var t in map.MapPanel.GetComponentsInChildren<Text>())if(t.transform.parent==map.MapPanel&&t!=map.MapInfo)t.gameObject.SetActive(false);
  map.MapPanel.anchorMin=new Vector2(.04f,.06f);map.MapPanel.anchorMax=new Vector2(.96f,.94f);map.MapPanel.sizeDelta=Vector2.zero;map.MapPanel.anchoredPosition=Vector2.zero;
  Icon(map.MapPanel,HUDShape.Target,new Vector2(51,-43),new Vector2(38,42),new Color(.75f,.68f,1));Label(map.MapPanel,"Modern map title","EL RIFT",new Vector2(84,-16),new Vector2(400,50),32);
  Label(map.MapPanel,"Map subtitle","EXPLORACIÓN",new Vector2(85,-67),new Vector2(400,25),13).color=new Color(.7f,.68f,.81f);
  sidebar=Rect(map.MapPanel,"Map navigation",new Vector2(0,0),new Vector2(0,1),new Vector2(174,-15),new Vector2(300,-190));Fill(sidebar,new Color(.045f,.047f,.07f,.35f));
  Label(sidebar,"Map section","VISTA DEL MAPA",new Vector2(0,0),new Vector2(300,26),14).color=new Color(.68f,.66f,.78f);
  var general=Action(sidebar,"General map","Mapa general",new Vector2(0,-42),new Vector2(300,52),FitOverview);var active=general.GetComponent<RiftMapSurface>();active.Fill=new Color(.22f,.1f,.38f,.8f);active.Border=new Color(.65f,.39f,1);active.Glow=7;Icon(general.transform,HUDShape.Ornament,new Vector2(26,-26),new Vector2(28,28),new Color(.87f,.78f,1));
  Divider(sidebar,-120,300);Label(sidebar,"Filters title","MOSTRAR",new Vector2(0,-145),new Vector2(300,28),14);
  crystals=Action(sidebar,"Filter checkpoints","Cristales y refugios   ●",new Vector2(0,-192),new Vector2(300,48),()=>{showCrystals=!showCrystals;RefreshFilters();});
  encounters=Action(sidebar,"Filter encounters","Encuentros                ●",new Vector2(0,-251),new Vector2(300,48),()=>{showEncounters=!showEncounters;RefreshFilters();});
  ToggleArt(crystals,HUDShape.Crystal);ToggleArt(encounters,HUDShape.Target);
  Divider(sidebar,-330,300);Label(sidebar,"Selected area title","ZONA SELECCIONADA",new Vector2(0,-350),new Vector2(300,30),14);
  map.MapInfo.rectTransform.SetParent(sidebar,false);map.MapInfo.rectTransform.anchorMin=map.MapInfo.rectTransform.anchorMax=new Vector2(0,1);map.MapInfo.rectTransform.pivot=new Vector2(0,1);map.MapInfo.rectTransform.anchoredPosition=new Vector2(0,-397);map.MapInfo.rectTransform.sizeDelta=new Vector2(300,105);map.MapInfo.fontSize=17;map.MapInfo.color=TextColor;map.MapInfo.alignment=TextAnchor.UpperLeft;
  var center=Action(sidebar,"Recenter map","Centrar en mi posición",new Vector2(0,-525),new Vector2(300,52),Recenter);Icon(center.transform,HUDShape.Target,new Vector2(25,-26),new Vector2(25,27),TextColor);
  var footer=Label(map.MapPanel,"Map controls","Rueda: zoom     ·     Arrastrar: mover     ·     M / Esc: cerrar",Vector2.zero,new Vector2(1100,40),15);footer.rectTransform.anchorMin=footer.rectTransform.anchorMax=new Vector2(0,0);footer.rectTransform.anchoredPosition=new Vector2(30,55);footer.rectTransform.pivot=new Vector2(0,1);footer.color=new Color(.75f,.73f,.83f);
  var closeGraphic=map.CloseButton.GetComponent<RiftHUDGraphic>();if(closeGraphic)closeGraphic.enabled=false;var close=Fill(Rect(map.CloseButton.transform,"Close background",Vector2.zero,Vector2.one,Vector2.zero,Vector2.zero),new Color(.12f,.11f,.19f,.75f));close.raycastTarget=true;close.transform.SetAsFirstSibling();map.CloseButton.targetGraphic=close;foreach(var t in map.CloseButton.GetComponentsInChildren<Text>()){t.text="×";t.color=TextColor;}
  map.CloseButton.GetComponent<RectTransform>().anchoredPosition=new Vector2(-37,-37);
  map.Viewport.anchorMin=new Vector2(0,.11f);map.Viewport.anchorMax=new Vector2(.985f,.90f);map.Viewport.offsetMin=new Vector2(350,0);map.Viewport.offsetMax=Vector2.zero;
  // Borders are native geometry, scoped to this screen; no shared HUD theme mutation.
  var viewportBorder=Surface(Rect(map.MapPanel,"Cartography viewport border",map.Viewport.anchorMin,map.Viewport.anchorMax,Vector2.zero,Vector2.zero),Color.clear,new Color(.43f,.40f,.54f,.95f),7);viewportBorder.rectTransform.offsetMin=map.Viewport.offsetMin;viewportBorder.rectTransform.offsetMax=map.Viewport.offsetMax;viewportBorder.Glow=1.5f;viewportBorder.raycastTarget=false;
  // Rounded perimeter is part of the smoked-glass surface, not the legacy gold graphic.
 }
 public void PrepareOpen(){var parent=map.MapPanel.parent as RectTransform;float height=Mathf.Min(parent.rect.height*.64f,parent.rect.height-350);height=Mathf.Max(400,height);float rightReserve=230,leftMargin=24;float available=Mathf.Max(700,parent.rect.width-rightReserve-leftMargin);float width=Mathf.Min(available,(350+height*.79f*(map.MapImage.texture?(float)map.MapImage.texture.width/map.MapImage.texture.height:1))/.985f);map.MapPanel.anchorMin=map.MapPanel.anchorMax=new Vector2(.5f,.5f);map.MapPanel.sizeDelta=new Vector2(width,height);map.MapPanel.anchoredPosition=new Vector2(-rightReserve*.5f,parent.rect.height*.5f-24-height*.5f);
  // Fit the overlay between the fixed combat frames and minimap; never relocate HUD widgets.
  float navigationScale=Mathf.Min(1,(height-180)/580);sidebar.anchorMin=sidebar.anchorMax=new Vector2(0,1);sidebar.pivot=new Vector2(0,1);sidebar.anchoredPosition=new Vector2(24,-110);sidebar.sizeDelta=new Vector2(300,580);sidebar.localScale=Vector3.one*navigationScale;map.Viewport.offsetMin=new Vector2(44+300*navigationScale,0);var border=map.MapPanel.Find("Cartography viewport border") as RectTransform;if(border)border.offsetMin=map.Viewport.offsetMin;
  Canvas.ForceUpdateCanvases();var size=map.Viewport.rect.size;float aspect=map.MapImage.texture?(float)map.MapImage.texture.width/map.MapImage.texture.height:1;float fit=Mathf.Min(size.x/aspect,size.y);map.Content.sizeDelta=new Vector2(fit*aspect,fit);}

 void LateUpdate(){if(!map)return;map.MapButton.gameObject.SetActive(true);if(!map.MapOpen){RestoreHUD();previousOpen=false;return;}if(!previousOpen){map.MapInfo.text="Seleccioná un cristal o encuentro para ver su ubicación.";previousOpen=true;FitOverview();StyleLabels();Recenter();var hud=FindFirstObjectByType<RiftGameplayHUD>();if(hud){gameplayVisibility=hud.GetComponent<CanvasGroup>();ownVisibility=!gameplayVisibility;if(ownVisibility)gameplayVisibility=hud.gameObject.AddComponent<CanvasGroup>();oldAlpha=gameplayVisibility.alpha;oldBlocks=gameplayVisibility.blocksRaycasts;oldInteractable=gameplayVisibility.interactable;}}
  if(gameplayVisibility){gameplayVisibility.alpha=1;gameplayVisibility.blocksRaycasts=false;gameplayVisibility.interactable=false;}RefreshFilters();}
 void RestoreHUD(){if(!gameplayVisibility)return;gameplayVisibility.alpha=oldAlpha;gameplayVisibility.blocksRaycasts=oldBlocks;gameplayVisibility.interactable=oldInteractable;if(ownVisibility)Destroy(gameplayVisibility);gameplayVisibility=null;ownVisibility=false;}
 void OnDisable(){RestoreHUD();previousOpen=false;if(map&&map.MapButton)map.MapButton.gameObject.SetActive(true);}
 void RefreshFilters(){if(!map)return;foreach(Transform child in map.Content){var tip=child.GetComponent<RiftTooltipTrigger>();if(!tip)continue;child.gameObject.SetActive(tip.Description=="Zona de encuentro"?showEncounters:showCrystals);}SetFilter(crystals,showCrystals);SetFilter(encounters,showEncounters);}
 void SetFilter(Button b,bool on){if(!b)return;var surface=b.GetComponent<RiftMapSurface>();surface.Fill=on?new Color(.12f,.09f,.19f,.4f):new Color(.085f,.085f,.11f,.28f);surface.SetVerticesDirty();var t=b.GetComponentInChildren<Text>();t.text=b.name=="Filter checkpoints"?"Cristales y refugios":"Encuentros";t.color=on?TextColor:new Color(.57f,.56f,.63f);var track=b.transform.Find("Toggle track").GetComponent<RiftMapSurface>();track.Fill=on?Violet:new Color(.2f,.2f,.26f);track.Border=on?new Color(.8f,.67f,1):Line;track.SetVerticesDirty();track.transform.Find("Toggle knob").GetComponent<RectTransform>().anchoredPosition=new Vector2(on?10:-10,0);}
 void StyleLabels(){foreach(Transform pin in map.Content)foreach(var text in pin.GetComponentsInChildren<Text>()){text.fontSize=14;text.color=TextColor;if(!text.GetComponent<Shadow>()){var shadow=text.gameObject.AddComponent<Shadow>();shadow.effectColor=new Color(0,0,0,.9f);shadow.effectDistance=new Vector2(1,-1);}}}
 public void FitOverview(){map.SetZoom(1);map.Content.anchoredPosition=Vector2.zero;}
 public void Recenter(){var actor=ClientFrontend.ClientPlayerInstance?ClientFrontend.ClientPlayerInstance.MyCharacter:null;if(actor){var locator=map.PlayerMarker.GetComponent<RiftMapPlayerLocator>();var combat=ClientFrontend.ClientPlayerInstance.GetComponent<MultiFPS.Gameplay.RiftCombat.AbilityController>();locator.ShowLocal(actor.transform.position,actor.Input.LookY,actor.Health.CharacterName,combat?combat.Level:0);locator.Center();}}
 }
 // Rounded surfaces and small glow rings are UI geometry. No textures, blur pass or global material changes.
 [RequireComponent(typeof(CanvasRenderer))]public sealed class RiftMapSurface:MaskableGraphic {
  public Color Fill=new Color(.1f,.1f,.15f,.8f),Border=new Color(.5f,.46f,.65f);public float Radius=8,Glow;
  List<Vector2> Ring(Rect r,float radius){var points=new List<Vector2>();float rad=Mathf.Min(radius,Mathf.Min(r.width,r.height)*.5f);var centers=new[]{new Vector2(r.xMax-rad,r.yMin+rad),new Vector2(r.xMax-rad,r.yMax-rad),new Vector2(r.xMin+rad,r.yMax-rad),new Vector2(r.xMin+rad,r.yMin+rad)};for(int k=0;k<4;k++)for(int j=0;j<=6;j++){float a=(-90+k*90+j*15)*Mathf.Deg2Rad;points.Add(centers[k]+new Vector2(Mathf.Cos(a),Mathf.Sin(a))*rad);}return points;}
  void Band(VertexHelper vh,List<Vector2> a,List<Vector2> b,Color tint){for(int i=0;i<a.Count;i++){int j=(i+1)%a.Count,n=vh.currentVertCount;vh.AddVert(a[i],tint*color,Vector2.zero);vh.AddVert(a[j],tint*color,Vector2.zero);vh.AddVert(b[j],tint*color,Vector2.zero);vh.AddVert(b[i],tint*color,Vector2.zero);vh.AddTriangle(n,n+1,n+2);vh.AddTriangle(n,n+2,n+3);}}
  protected override void OnPopulateMesh(VertexHelper vh){vh.Clear();var r=rectTransform.rect;if(r.width<2||r.height<2)return;var edge=Ring(r,Radius);var innerRect=new Rect(r.x+1,r.y+1,r.width-2,r.height-2);var inner=Ring(innerRect,Mathf.Max(0,Radius-1));int center=vh.currentVertCount;vh.AddVert(r.center,Fill*color,Vector2.zero);foreach(var p in inner)vh.AddVert(p,Fill*color,Vector2.zero);for(int i=0;i<inner.Count;i++)vh.AddTriangle(center,center+1+i,center+1+(i+1)%inner.Count);Band(vh,edge,inner,Border);if(Glow>0)for(int i=0;i<4;i++){float d=(i+1)*Glow/4;var expanded=new Rect(r.x-d,r.y-d,r.width+d*2,r.height+d*2);var next=Ring(expanded,Radius+d);var tint=Border;tint.a*=.19f*(1-i*.2f);Band(vh,next,edge,tint);edge=next;}}
 }
